CREATE OR REPLACE FUNCTION public.admin_bug_report_status(report_id uuid, new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if new_status is null or new_status not in ('open','resolved') then raise exception 'Invalid report status.'; end if;
  update public.bug_reports set status=new_status where id=report_id;
  if not found then raise exception 'Report not found.'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.admin_delete_restaurant(target_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare images text[]; r public.restaurants; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  select * into r from public.restaurants where id=target_id for update;
  if not found then raise exception 'Restaurant not found.'; end if;
  select coalesce(array_agg(distinct image),'{}') into images from unnest(r.image_paths||array[r.cover_image_path,r.plate_image_path]) image where image is not null;
  update public.app_config set spot_of_day_restaurant_id=null,spot_date=null,plate_image_path=null,updated_at=now()
    where spot_of_day_restaurant_id=target_id;
  delete from public.restaurants where id=target_id;
  return images;
end $function$

CREATE OR REPLACE FUNCTION public.admin_list_profiles(after_id uuid DEFAULT NULL::uuid, page_size integer DEFAULT 30)
 RETURNS SETOF public_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare after_created timestamptz;
begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if page_size is null or page_size not between 1 and 100 then raise exception 'Invalid page size.'; end if;
  if after_id is not null then
    select created_at into after_created from public.public_profiles where id = after_id;
    if not found then raise exception 'Invalid user cursor. Refresh the list.'; end if;
  end if;
  return query select p.* from public.public_profiles p
    where after_id is null or (p.created_at, p.id) < (after_created, after_id)
    order by p.created_at desc, p.id desc limit page_size + 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_moderate_content(content_kind text, target_id uuid, moderation_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tab text; affected integer; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  tab := case content_kind when 'review' then 'reviews' when 'comment' then 'review_comments'
    when 'post' then 'posts' when 'post_comment' then 'post_comments' end;
  if tab is null or target_id is null or moderation_action is null then raise exception 'Invalid moderation action.'; end if;
  if content_kind='review' and moderation_action in ('hide','restore') then
    update public.reviews set is_hidden=(moderation_action='hide') where id=target_id;
    get diagnostics affected=row_count;
  elsif moderation_action='delete' then
    execute format('delete from public.%I where id=$1',tab) using target_id;
    get diagnostics affected=row_count;
  else raise exception 'Invalid moderation action.'; end if;
  if affected=0 then raise exception 'Content not found.'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.admin_patch_app_control(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();r public.app_control;k text;v jsonb;begin
 if not public.is_admin()then raise exception 'Admin access required.';end if;
 if payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Invalid app control.';end if;
 for k,v in select * from jsonb_each(payload)loop
  if k not in('maintenance','maintenance_message','min_version','latest_version','update_message','ios_url','android_url')then raise exception 'Invalid app control field.';end if;
  if k='maintenance'then
   if jsonb_typeof(v)<>'boolean'then raise exception 'Invalid maintenance flag.';end if;
  elsif jsonb_typeof(v)not in('string','null')then raise exception 'Invalid app control value.';end if;
  if k in('maintenance_message','update_message')and length(v#>>'{}')>500 then raise exception 'App message too long.';end if;
  if k in('min_version','latest_version')and v<>'null'::jsonb and(v#>>'{}')<>''
   and(length(v#>>'{}')>20 or(v#>>'{}')!~'^[0-9]+([.][0-9]+)*$')then raise exception 'Invalid app version.';end if;
  if k in('ios_url','android_url')and v<>'null'::jsonb and(v#>>'{}')<>''
   and(length(v#>>'{}')>512 or(v#>>'{}')!~'^https://[^[:space:]]+$')then raise exception 'Invalid store URL.';end if;
 end loop;
 insert into public.app_control(id)values(true)on conflict(id)do nothing;
 select * into r from public.app_control where id=true for update;
 r:=jsonb_populate_record(r,payload);
 update public.app_control set maintenance=r.maintenance,maintenance_message=r.maintenance_message,min_version=r.min_version,
  latest_version=r.latest_version,update_message=r.update_message,ios_url=r.ios_url,android_url=r.android_url,updated_at=now()where id=true;
 return public.public_app_configuration()->'control';
end $function$

CREATE OR REPLACE FUNCTION public.admin_patch_display_plans(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();r public.app_config;k text;v jsonb;feature_products text[];listing_products text[];begin
 if not public.is_admin()then raise exception 'Admin access required.';end if;
 if payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Invalid plan catalog.';end if;
 for k,v in select * from jsonb_each(payload)loop
  if k not in('feature_plans','listing_plans')then raise exception 'Invalid plan catalog field.';end if;
  perform public.validate_display_plans(v,case when k='feature_plans'then 'feature'else 'listing'end);
 end loop;
 insert into public.app_config(id)values(true)on conflict(id)do nothing;
 select * into r from public.app_config where id=true for update;
 r:=jsonb_populate_record(r,payload);
 select array_agg(value->>'productId')into feature_products from jsonb_array_elements(coalesce(r.feature_plans,'[]'))where value?'productId';
 select array_agg(value->>'productId')into listing_products from jsonb_array_elements(coalesce(r.listing_plans,'[]'))where value?'productId';
 if exists(select 1 from unnest(coalesce(feature_products,'{}')||array['feature_7d','feature_30d'])p
  where p=any(coalesce(listing_products,'{}')||array['listing_1yr']))then raise exception 'Product cannot be both feature and listing.';end if;
 update public.app_config set feature_plans=r.feature_plans,listing_plans=r.listing_plans,updated_at=now()where id=true;
 return jsonb_build_object('feature_plans',r.feature_plans,'listing_plans',r.listing_plans);
end $function$

CREATE OR REPLACE FUNCTION public.admin_queue_page(queue_kind text, after_id uuid DEFAULT NULL::uuid, page_size integer DEFAULT 50, filter_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tab text := public.report_queue_table(queue_kind); after_created timestamptz; rows jsonb; predicate text := 'true'; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if tab is null or page_size is null or page_size not between 1 and 100 then raise exception 'Invalid queue or page size.'; end if;
  if filter_status is not null then
    if queue_kind<>'claim' or filter_status not in ('pending','approved','rejected') then raise exception 'Invalid queue status.'; end if;
    predicate := format('status::text=%L',filter_status);
  end if;
  if after_id is not null then
    execute format('select created_at from public.%I where id=$1',tab) into after_created using after_id;
    if after_created is null then raise exception 'Invalid queue cursor. Refresh the list.'; end if;
  end if;
  execute format('select coalesce(jsonb_agg(to_jsonb(p)),''[]''::jsonb) from (select * from public.%I where %s and ($1 is null or (created_at,id)<($2,$1)) order by created_at desc,id desc limit $3) p',tab,predicate)
    into rows using after_id,after_created,page_size+1;
  return rows;
end $function$

CREATE OR REPLACE FUNCTION public.admin_rebuild_restaurant_search()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scanned bigint; updated bigint; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  select count(*) into scanned from public.restaurants;
  update public.restaurants r set search_text=public.restaurant_search_value(r)
    where search_text is distinct from public.restaurant_search_value(r);
  get diagnostics updated=row_count;
  return jsonb_build_object('scanned',scanned,'updated',updated);
end $function$

CREATE OR REPLACE FUNCTION public.admin_restaurant_page(search_term text DEFAULT ''::text, filter_status text DEFAULT 'all'::text, after_id uuid DEFAULT NULL::uuid, page_size integer DEFAULT 25, claimed_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cursor_row public.restaurants; result jsonb; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if page_size is null or page_size not between 1 and 100 or filter_status is null or filter_status not in ('all','active','pending')
    or length(coalesce(search_term,''))>200 or claimed_only is null then raise exception 'Invalid restaurant query.'; end if;
  if after_id is not null then
    select * into cursor_row from public.restaurants where id=after_id;
    if not found then raise exception 'Invalid restaurant cursor. Refresh the list.'; end if;
  end if;
  with matches as (select * from public.restaurants r where
    (filter_status='all' or r.is_active=(filter_status='active')) and (not claimed_only or r.owner_id is not null)
    and strpos(r.search_text,lower(btrim(coalesce(search_term,''))))>0),
  page as (select * from matches where after_id is null or (created_at,id)<(cursor_row.created_at,after_id)
    order by created_at desc,id desc limit page_size+1)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
    'total',(select count(*) from matches)) into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_review_claim(claim_id uuid, decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claim public.restaurant_claims; restaurant public.restaurants; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if decision is null or decision not in ('approved','rejected') then raise exception 'Invalid claim decision.'; end if;
  select * into claim from public.restaurant_claims where id=claim_id for update;
  if not found then raise exception 'Claim not found.'; end if;
  if claim.status::text=decision then return; end if;
  if claim.status<>'pending' then raise exception 'This claim was already reviewed.'; end if;
  if decision='approved' then
    if not exists(select 1 from public.profiles where id=claim.user_id and not is_banned)
      or exists(select 1 from public.auth_signup_pending where user_id=claim.user_id) then raise exception 'Claimant account is not active.'; end if;
    select * into restaurant from public.restaurants where id=claim.restaurant_id for update;
    if not found then raise exception 'Restaurant not found.'; end if;
    if restaurant.owner_id is not null and restaurant.owner_id<>claim.user_id then raise exception 'Restaurant already has another owner.'; end if;
    update public.restaurants set owner_id=claim.user_id,
      listing_paid_until=greatest(coalesce(listing_paid_until,now()),now()+interval '30 days') where id=claim.restaurant_id;
    insert into public.restaurant_menus(restaurant_id,owner_id) values(claim.restaurant_id,claim.user_id)
      on conflict(restaurant_id) do update set owner_id=excluded.owner_id;
  end if;
  update public.restaurant_claims set status=decision::public.claim_status,reviewed_at=now(),reviewed_by=auth.uid(),updated_at=now() where id=claim_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_restaurant_owner(target_id uuid, new_owner uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if new_owner is not null and (not exists(select 1 from public.profiles where id=new_owner and not is_banned)
    or exists(select 1 from public.auth_signup_pending where user_id=new_owner)) then raise exception 'Owner account is not active.'; end if;
  perform 1 from public.restaurants where id=target_id for update;
  if not found then raise exception 'Restaurant not found.'; end if;
  update public.restaurants set owner_id=new_owner where id=target_id;
  if new_owner is null then delete from public.restaurant_menus where restaurant_id=target_id;
  else insert into public.restaurant_menus(restaurant_id,owner_id) values(target_id,new_owner)
    on conflict(restaurant_id) do update set owner_id=excluded.owner_id; end if;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_spot_of_day(restaurant_id uuid, pin_date date DEFAULT NULL::date, plate_path text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if restaurant_id is not null then
    perform 1 from public.restaurants where id=restaurant_id and is_active for update;
    if not found then raise exception 'Choose an active restaurant for the spotlight.'; end if;
    if plate_path is not null and plate_path !~ '^(rest|rev)/[0-9a-fA-F-]{36}/[a-zA-Z0-9._-]+\.(jpg|png|webp)$' then raise exception 'Invalid spotlight image.'; end if;
  end if;
  insert into public.app_config(id,spot_of_day_restaurant_id,spot_date,plate_image_path,updated_at)
    values(true,restaurant_id,case when restaurant_id is null then null else pin_date end,
      case when restaurant_id is null then null else plate_path end,now())
    on conflict(id) do update set spot_of_day_restaurant_id=excluded.spot_of_day_restaurant_id,
      spot_date=excluded.spot_date,plate_image_path=excluded.plate_image_path,updated_at=now();
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_user_banned(target_id uuid, banned boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if target_id is null or banned is null then raise exception 'Invalid user update.'; end if;
  if target_id = auth.uid() then raise exception 'You cannot suspend your own account.'; end if;
  perform 1 from public.profiles where id = target_id for update;
  if not found then raise exception 'User not found.'; end if;
  update public.profiles set is_banned = banned where id = target_id;
  if banned then delete from public.push_tokens where user_id = target_id; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_write_restaurant(payload jsonb, target_id uuid DEFAULT NULL::uuid)
 RETURNS restaurants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.restaurants; result public.restaurants; begin
  if not public.is_admin() then raise exception 'Admin access required.'; end if;
  if target_id is not null then
    select * into r from public.restaurants where id=target_id for update;
    if not found then raise exception 'Restaurant not found.'; end if;
  end if;
  r:=public.checked_restaurant_patch(r,payload,true);
  if target_id is null then
    insert into public.restaurants(name,slug,description,address,parish,city,latitude,longitude,phone_number,website_url,
      instagram_handle,price_range,cuisines,categories,image_paths,cover_image_path,opening_hours,menu,added_by,search_text,is_active,is_verified,is_featured)
    values(r.name,regexp_replace(lower(r.name),'[^a-z0-9]+','-','g')||'-'||gen_random_uuid()::text,r.description,r.address,r.parish,
      r.city,r.latitude,r.longitude,r.phone_number,r.website_url,r.instagram_handle,r.price_range,r.cuisines,r.categories,
      r.image_paths,r.cover_image_path,r.opening_hours,r.menu,auth.uid(),r.search_text,coalesce(r.is_active,false),coalesce(r.is_verified,false),coalesce(r.is_featured,false)) returning * into result;
  else
    update public.restaurants set name=r.name,description=r.description,address=r.address,parish=r.parish,city=r.city,
      latitude=r.latitude,longitude=r.longitude,phone_number=r.phone_number,website_url=r.website_url,instagram_handle=r.instagram_handle,
      price_range=r.price_range,cuisines=r.cuisines,categories=r.categories,image_paths=r.image_paths,cover_image_path=r.cover_image_path,
      opening_hours=r.opening_hours,menu=r.menu,search_text=r.search_text,is_active=r.is_active,is_verified=r.is_verified,is_featured=r.is_featured
      where id=target_id returning * into result;
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.change_collection_membership(collection_id uuid, restaurant_id uuid, should_add boolean)
 RETURNS collections
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();result public.collections;begin
 if collection_id is null or restaurant_id is null or should_add is null then raise exception 'Invalid collection membership.';end if;
 select * into result from public.collections where id=collection_id and owner_id=caller for update;
 if not found then raise exception 'Collection not found or permission denied.';end if;
 if should_add then
  if not exists(select 1 from public.restaurants where id=restaurant_id and is_active)then raise exception 'Restaurant unavailable.';end if;
  if not restaurant_id=any(result.restaurant_ids)then result.restaurant_ids:=array_append(result.restaurant_ids,restaurant_id);end if;
 else result.restaurant_ids:=array_remove(result.restaurant_ids,restaurant_id);end if;
 if result.cover_restaurant_id is null or not result.cover_restaurant_id=any(result.restaurant_ids)then result.cover_restaurant_id:=result.restaurant_ids[1];end if;
 update public.collections set restaurant_ids=result.restaurant_ids,cover_restaurant_id=result.cover_restaurant_id where id=collection_id and owner_id=caller returning * into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.checked_restaurant_patch(current_row restaurants, payload jsonb, admin_mode boolean)
 RETURNS restaurants
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.restaurants; k text; v jsonb; tag text; day jsonb; slot jsonb; image text; begin
  if payload is null or jsonb_typeof(payload)<>'object' then raise exception 'Invalid restaurant details.'; end if;
  for k,v in select key,value from jsonb_each(payload) loop
    if k not in ('name','description','address','parish','city','latitude','longitude','phone_number','website_url',
      'instagram_handle','price_range','cuisines','categories','image_paths','cover_image_path','opening_hours','menu')
      and not (admin_mode and k in ('is_active','is_verified','is_featured')) then raise exception 'Invalid restaurant field: %',k; end if;
    if k in ('latitude','longitude') and jsonb_typeof(v)<>'number' then raise exception 'Invalid location.';
    elsif k in ('is_active','is_verified','is_featured') and jsonb_typeof(v)<>'boolean' then raise exception 'Invalid restaurant flag.';
    elsif k in ('cuisines','categories','image_paths') then
      if jsonb_typeof(v)<>'array' or exists(select 1 from jsonb_array_elements(v) e where jsonb_typeof(e)<>'string') then raise exception 'Invalid restaurant tags or images.'; end if;
    elsif k in ('name','address','parish') and jsonb_typeof(v)<>'string' then raise exception 'Invalid restaurant details.';
    elsif k in ('description','city','phone_number','website_url','instagram_handle','price_range','cover_image_path')
      and jsonb_typeof(v) not in ('string','null') then raise exception 'Invalid restaurant details.'; end if;
  end loop;
  r:=jsonb_populate_record(current_row,payload);
  r.name:=btrim(r.name); r.address:=btrim(r.address);
  r.description:=nullif(btrim(r.description),''); r.city:=nullif(btrim(r.city),'');
  r.phone_number:=nullif(btrim(r.phone_number),''); r.website_url:=nullif(btrim(r.website_url),'');
  r.instagram_handle:=nullif(regexp_replace(btrim(r.instagram_handle),'^@+',''),'');
  if r.name is null or length(r.name) not between 2 and 160 or r.address is null or length(r.address) not between 1 and 500
    or r.parish is null or r.parish not in ('kingston','st_andrew','st_thomas','portland','st_mary','st_ann','trelawny',
      'st_james','hanover','westmoreland','st_elizabeth','manchester','clarendon','st_catherine')
    or r.latitude is null or r.longitude is null or r.latitude not between -90 and 90 or r.longitude not between -180 and 180
    or (r.latitude=0 and r.longitude=0) then raise exception 'Check the restaurant name, address, parish and location.'; end if;
  if length(coalesce(r.description,''))>4000 or length(coalesce(r.city,''))>160 or length(coalesce(r.phone_number,''))>100
    or length(coalesce(r.instagram_handle,''))>100 or length(coalesce(r.website_url,''))>2048
    or (r.website_url is not null and r.website_url !~* '^https?://[^[:space:]]+$')
    or (r.price_range is not null and r.price_range not in ('$','$$','$$$','$$$$')) then raise exception 'Check the restaurant contact details.'; end if;
  if cardinality(coalesce(r.cuisines,'{}'))>100 or cardinality(coalesce(r.categories,'{}'))>100 then raise exception 'Too many tags.'; end if;
  foreach tag in array coalesce(r.cuisines,'{}')||coalesce(r.categories,'{}') loop
    if tag is null or length(btrim(tag))>80 then raise exception 'Invalid restaurant tag.'; end if;
  end loop;
  select coalesce(array_agg(t order by first_pos),'{}') into r.cuisines from
    (select lower(btrim(value)) t,min(pos) first_pos from unnest(coalesce(r.cuisines,'{}')) with ordinality a(value,pos)
      where btrim(value)<>'' group by lower(btrim(value))) s;
  select coalesce(array_agg(t order by first_pos),'{}') into r.categories from
    (select lower(btrim(value)) t,min(pos) first_pos from unnest(coalesce(r.categories,'{}')) with ordinality a(value,pos)
      where btrim(value)<>'' group by lower(btrim(value))) s;
  if cardinality(r.cuisines)+cardinality(r.categories)=0 then raise exception 'Please pick at least one cuisine or category.'; end if;
  r.image_paths:=coalesce(r.image_paths,'{}');
  if cardinality(r.image_paths)>20 then raise exception 'Too many restaurant images.'; end if;
  foreach image in array r.image_paths||case when r.cover_image_path is null then '{}'::text[] else array[r.cover_image_path] end loop
    if image is null or image !~ '^rest/[0-9a-fA-F-]{36}/[a-zA-Z0-9._-]+\.(jpg|png|webp)$'
      or (not admin_mode and split_part(image,'/',2)<>auth.uid()::text) then raise exception 'Invalid restaurant image.'; end if;
  end loop;
  if current_row.id is null and not (payload ? 'cover_image_path') then r.cover_image_path:=r.image_paths[1]; end if;
  r.menu:=coalesce(nullif(r.menu,'null'::jsonb),'[]'::jsonb);
  perform public.validate_restaurant_menu(r.menu);
  if r.opening_hours='null'::jsonb then r.opening_hours:=null; end if;
  if r.opening_hours is not null then
    if jsonb_typeof(r.opening_hours)<>'object' or exists(select 1 from jsonb_object_keys(r.opening_hours) d
      where d not in ('mon','tue','wed','thu','fri','sat','sun')) then raise exception 'Invalid opening hours.'; end if;
    for day in select value from jsonb_each(r.opening_hours) loop
      if jsonb_typeof(day)<>'array' then raise exception 'Invalid opening hours.'; end if;
      if jsonb_array_length(day)>10 then raise exception 'Too many opening-hour intervals.'; end if;
      for slot in select value from jsonb_array_elements(day) loop
        if jsonb_typeof(slot)<>'object' or slot->>'open' is null or slot->>'close' is null
          or slot->>'open' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or slot->>'close' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Invalid opening hours.'; end if;
      end loop;
    end loop;
  end if;
  r.search_text:=public.restaurant_search_value(r);
  return r;
end $function$

CREATE OR REPLACE FUNCTION public.claim_admin_media_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job public.media_cleanup; result jsonb:='[]'; begin
 if not public.is_admin() then raise exception 'Admin access required.'; end if;
 for job in select * from public.media_cleanup where state='queued' or (state='processing' and lease_until<=now()) order by key limit 20 loop
 if not pg_try_advisory_xact_lock(hashtextextended(job.key,17017)) then continue; end if;
 select * into job from public.media_cleanup where key=job.key and (state='queued' or (state='processing' and lease_until<=now())) for update skip locked;
 if not found then continue; end if;
 if public.media_is_referenced(job.key) then delete from public.media_cleanup where key=job.key; continue; end if;
 update public.media_cleanup set state='processing',lease_id=gen_random_uuid(),lease_owner=auth.uid(),lease_until=now()+interval '5 minutes',attempts=attempts+1 where key=job.key returning * into job;
 result:=result||jsonb_build_array(jsonb_build_object('key',job.key,'lease_id',job.lease_id));
 end loop; return result;
end $function$

CREATE OR REPLACE FUNCTION public.claim_my_media_cleanup(object_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account(); job public.media_cleanup; begin
 if object_key is null or object_key !~ '^(rest|rev|usr|post)/[0-9a-fA-F-]{36}/[a-zA-Z0-9._-]+\.(jpg|png|webp)$' or split_part(object_key,'/',2)<>caller::text then raise exception 'Only your own image can be removed.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(object_key,17017));
 if public.media_is_referenced(object_key) then raise exception 'This image is still in use.'; end if;
 insert into public.media_cleanup(key) values(object_key) on conflict(key) do nothing;
 select * into job from public.media_cleanup where key=object_key for update;
 if job.state='done' then return jsonb_build_object('done',true); end if;
 if job.state='processing' and job.lease_until>now() then raise exception 'This image is already being removed.'; end if;
 update public.media_cleanup set state='processing',lease_id=gen_random_uuid(),lease_owner=caller,lease_until=now()+interval '5 minutes',attempts=attempts+1 where key=object_key returning * into job;
 return jsonb_build_object('key',job.key,'lease_id',job.lease_id);
end $function$

CREATE OR REPLACE FUNCTION public.complete_account_deletion(target_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare result jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended(target_user::text,21021));
 if exists(select 1 from auth.users where id=target_user)then raise exception 'Auth deletion is not complete.';end if;
 update public.account_deletion_jobs set state='completed',completed_at=coalesce(completed_at,now()),summary=summary||'{"authAccountDeleted":true}'::jsonb where user_id=target_user returning summary into result;
 if not found then raise exception 'Deletion was not prepared.';end if;return result;
end $function$

CREATE OR REPLACE FUNCTION public.delete_member_collection(target_collection uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();begin
 if target_collection is null then raise exception 'Invalid collection.';end if;
 delete from public.collections where id=target_collection and owner_id=caller;
 if not found then raise exception 'Collection not found or permission denied.';end if;
 return target_collection;
end $function$

CREATE OR REPLACE FUNCTION public.finish_auth_signup(chosen_username text, chosen_display_name text, chosen_avatar text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := auth.uid();
  confirmed timestamptz;
  password_hash text;
  has_social_identity boolean;
begin
  if caller is null then raise exception 'Verify your email or sign in first.'; end if;
  perform 1 from public.auth_signup_pending where user_id = caller for update;
  if not found then raise exception 'This account is already set up. Please sign in.'; end if;
  select email_confirmed_at, encrypted_password into confirmed, password_hash
    from auth.users where id = caller;
  select exists(select 1 from auth.identities where user_id = caller and provider in ('google', 'apple'))
    into has_social_identity;
  if confirmed is null or (not has_social_identity and coalesce(password_hash, '') = '') then
    raise exception 'Verify your email and set a password before finishing signup.';
  end if;
  if chosen_username is null or chosen_username !~ '^[a-z0-9_]{3,20}$'
    or chosen_display_name is null or length(btrim(chosen_display_name)) not between 2 and 50 then
    raise exception 'Check your username and display name.';
  end if;
  if chosen_avatar is not null and (length(chosen_avatar) > 2048 or chosen_avatar !~ '^https://') then
    raise exception 'Invalid profile photo.';
  end if;
  if exists(select 1 from public.profiles where id = caller and is_banned) then
    raise exception 'This account has been suspended.';
  end if;
  begin
    update public.profiles set username = chosen_username, display_name = btrim(chosen_display_name),
      avatar_path = chosen_avatar,
      preferences = coalesce(preferences, '{}'::jsonb) || '{"onboardingPending":true}'::jsonb
    where id = caller;
    if not found then raise exception 'Profile not found.'; end if;
  exception when unique_violation then
    raise exception 'That username is already taken.';
  end;
  delete from public.auth_signup_pending where user_id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.fulfill_verified_purchase(target_intent uuid, proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare intent public.purchase_intents;s public.purchase_settings;ledger public.purchase_ledger;
 restaurant public.restaurants;purchased timestamptz;until timestamptz;k text;v jsonb;begin
 if proof is null or jsonb_typeof(proof)<>'object'then raise exception 'Invalid verified purchase.';end if;
 for k,v in select * from jsonb_each(proof)loop
  if k not in('rc_project_id','rc_purchase_id','buyer_id','app_id','store','environment','store_transaction_id','product_id','purchased_at')
   or jsonb_typeof(v)<>'string'or length(v#>>'{}')not between 1 and 255 then raise exception 'Invalid verified purchase field.';end if;
 end loop;
 if not proof?&array['rc_project_id','rc_purchase_id','buyer_id','app_id','store','environment','store_transaction_id','product_id','purchased_at']then raise exception 'Incomplete verified purchase.';end if;
 select * into s from public.purchase_settings where id=true for share;
 if not found or not s.enabled or s.rc_project_id is distinct from proof->>'rc_project_id'
  or s.environment is distinct from proof->>'environment'or proof->>'store'not in('APP_STORE','PLAY_STORE')
  or(s.allowed_apps->>(proof->>'app_id'))is distinct from proof->>'store'then raise exception 'Purchase route is not enabled for this app/store/environment.';end if;
 -- Global verified purchase lock, then buyer, intent and restaurant. Pin the
 -- buyer before intent locks so profile deletion/cascades cannot invert them.
 -- Unique constraints remain the final transaction-identity defense.
 perform pg_advisory_xact_lock(hashtextextended((proof->>'rc_project_id')||'/'||(proof->>'rc_purchase_id'),25));
 perform 1 from public.profiles where id=(proof->>'buyer_id')::uuid for share;
 if not found then raise exception 'Buyer needs an active account.';end if;
 select * into intent from public.purchase_intents where id=target_intent for update;
 if not found then raise exception 'Purchase intent is unavailable.';end if;
 if intent.buyer_id::text is distinct from proof->>'buyer_id'or intent.product_id is distinct from proof->>'product_id'then raise exception 'Verified purchase does not match intent.';end if;
 select * into ledger from public.purchase_ledger where(rc_project_id=proof->>'rc_project_id'and rc_purchase_id=proof->>'rc_purchase_id')
  or(app_id=proof->>'app_id'and store=proof->>'store'and environment=proof->>'environment'and store_transaction_id=proof->>'store_transaction_id');
 if found then
  if ledger.intent_id is distinct from intent.id or ledger.buyer_id is distinct from intent.buyer_id
   or ledger.product_id is distinct from intent.product_id or ledger.rc_purchase_id is distinct from proof->>'rc_purchase_id'
   or ledger.app_id is distinct from proof->>'app_id'or ledger.store is distinct from proof->>'store'
   or ledger.environment is distinct from proof->>'environment'or ledger.store_transaction_id is distinct from proof->>'store_transaction_id'then raise exception 'Purchase was already assigned or proof changed.';end if;
  return jsonb_build_object('fulfilled',true,'granted_until',ledger.granted_until);
 end if;
 if intent.fulfilled_at is not null then raise exception 'Purchase intent was already fulfilled.';end if;
 purchased:=(proof->>'purchased_at')::timestamptz;
 -- Delivery may be delayed: expire by verified purchase time, not delivery time.
 if not isfinite(purchased)or purchased<intent.created_at-interval '5 minutes'or purchased>intent.expires_at
  or purchased>clock_timestamp()+interval '5 minutes'then raise exception 'Purchase time does not match intent.';end if;
 perform 1 from public.profiles where id=intent.buyer_id and not is_banned for share;
 if not found or exists(select 1 from public.auth_signup_pending where user_id=intent.buyer_id)then raise exception 'Buyer needs an active account.';end if;
 select * into restaurant from public.restaurants where id=intent.restaurant_id for update;
 if not found or restaurant.owner_id is distinct from intent.buyer_id or not restaurant.is_active then raise exception 'Active restaurant ownership required.';end if;
 until:=greatest(clock_timestamp(),case when intent.kind='feature'then restaurant.featured_until else restaurant.listing_paid_until end)
  +make_interval(days=>intent.days);
 if not isfinite(until)then raise exception 'Paid window is not finite.';end if;
 insert into public.purchase_ledger(intent_id,buyer_id,restaurant_id,rc_project_id,rc_purchase_id,app_id,store,environment,store_transaction_id,product_id,kind,days,purchased_at,granted_until)
  values(intent.id,intent.buyer_id,intent.restaurant_id,proof->>'rc_project_id',proof->>'rc_purchase_id',proof->>'app_id',proof->>'store',proof->>'environment',proof->>'store_transaction_id',intent.product_id,intent.kind,intent.days,purchased,until);
 if intent.kind='feature'then update public.restaurants set is_featured=true,featured_until=until,updated_at=now()where id=intent.restaurant_id;
 else update public.restaurants set listing_paid_until=until,updated_at=now()where id=intent.restaurant_id;end if;
 update public.purchase_intents set fulfilled_at=clock_timestamp()where id=intent.id;
 return jsonb_build_object('fulfilled',true,'granted_until',until);
end $function$

CREATE OR REPLACE FUNCTION public.merge_my_preferences(preference_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();current_prefs jsonb;result jsonb;k text;v jsonb;
begin
 if preference_patch is null or jsonb_typeof(preference_patch)<>'object' or octet_length(preference_patch::text)>65536 then raise exception 'Invalid settings update.';end if;
 for k,v in select key,value from jsonb_each(preference_patch)loop
  if k in('notificationsEnabled','notifyOnLike','notifyOnComment','notifyOnFollow','notifyOnBroadcast','onboardingPending')then
   if jsonb_typeof(v)<>'boolean'then raise exception 'Invalid settings update.';end if;
  elsif k in('favoriteCuisines','favoriteParishes','seenBadgeIds')then
   if k='seenBadgeIds'and v='null'::jsonb then continue;end if;
   if jsonb_typeof(v)<>'array'then raise exception 'Invalid settings update.';end if;
   if jsonb_array_length(v)>1000 or exists(select 1 from jsonb_array_elements(v)a where jsonb_typeof(a)<>'string'or length(a#>>'{}')>100)then raise exception 'Invalid settings update.';end if;
   if k='favoriteParishes'and exists(select 1 from jsonb_array_elements_text(v)p where p not in('kingston','st_andrew','st_thomas','portland','st_mary','st_ann','trelawny','st_james','hanover','westmoreland','st_elizabeth','manchester','clarendon','st_catherine'))then raise exception 'Invalid settings update.';end if;
  elsif k in('usernameChangedAt','displayNameChangedAt')then
   if v='null'::jsonb then continue;end if;
   if jsonb_typeof(v)<>'string'or length(v#>>'{}')>100 then raise exception 'Invalid settings update.';end if;
   begin perform(v#>>'{}')::timestamptz;exception when invalid_datetime_format or datetime_field_overflow then raise exception 'Invalid settings update.';end;
  else raise exception 'Invalid settings update.';end if;
 end loop;
 select preferences into current_prefs from public.profiles where id=caller for update;
 result:=coalesce(current_prefs,'{}'::jsonb)||preference_patch;
 if octet_length(result::text)>65536 then raise exception 'Invalid settings update.';end if;
 update public.profiles set preferences=result where id=caller;return result;
end $function$

CREATE OR REPLACE FUNCTION public.my_purchase_intent(target_intent uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();r public.purchase_intents;until timestamptz;begin
 select * into r from public.purchase_intents where id=target_intent and buyer_id=caller;
 if not found then return null;end if;
 select granted_until into until from public.purchase_ledger where intent_id=r.id;
 return jsonb_build_object('id',r.id,'product_id',r.product_id,'kind',r.kind,'days',r.days,'expires_at',r.expires_at,'fulfilled',r.fulfilled_at is not null,'granted_until',until);
end $function$

CREATE OR REPLACE FUNCTION public.notify_social_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid; recipient uuid; event_type text; target_id uuid; target_key text; target_label text; actor_name text; pref_key text; prefs jsonb; message_title text; message_body text; message_data jsonb;
begin
 if TG_TABLE_NAME = 'follows' then
 actor := new.follower_id; recipient := new.following_id; event_type := 'follow';
 else
 actor := new.user_id;
 event_type := case when TG_TABLE_NAME in ('review_likes','post_likes') then 'like' else 'comment' end;
 if TG_TABLE_NAME in ('review_likes','review_comments') then
 target_id := new.review_id; target_key := 'reviewId'; target_label := 'review';
 select user_id into recipient from public.reviews where id = target_id and not is_hidden;
 else
 target_id := new.post_id; target_key := 'postId'; target_label := 'post';
 select user_id into recipient from public.posts where id = target_id;
 end if;
 end if;
 if recipient is null or recipient = actor then return null; end if;
 if not exists(select 1 from public.profiles where id = actor and not is_banned)
 or not exists(select 1 from public.profiles where id = recipient and not is_banned)
 or exists(select 1 from public.blocks where (blocker_id = actor and blocked_id = recipient) or (blocker_id = recipient and blocked_id = actor)) then return null; end if;
 select preferences into prefs from public.profiles where id = recipient;
 pref_key := case event_type when 'follow' then 'notifyOnFollow' when 'like' then 'notifyOnLike' else 'notifyOnComment' end;
 if prefs->'notificationsEnabled' = 'false'::jsonb or prefs->pref_key = 'false'::jsonb then return null; end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text || recipient::text || event_type || coalesce(target_id::text,''), 0));
 if exists(select 1 from public.notifications where user_id = recipient and actor_id = actor and type = event_type and not is_read and created_at > now() - interval '5 minutes' and (target_key is null or data->>target_key = target_id::text)) then return null; end if;
 select coalesce(nullif(trim(display_name),''),'Someone') into actor_name from public.profiles where id = actor;
 message_data := jsonb_build_object('actorName',actor_name);
 if target_key is not null then message_data := message_data || jsonb_build_object(target_key,target_id::text); end if;
 if event_type = 'follow' then
 message_title := 'New follower'; message_body := actor_name || ' started following you';
 elsif event_type = 'like' then
 message_title := 'New like'; message_body := actor_name || ' liked your ' || target_label;
 else
 message_title := 'New comment'; message_body := actor_name || ': ' || case when length(trim(new.text)) > 80 then rtrim(left(trim(new.text),77)) || '…' else trim(new.text) end;
 end if;
 insert into public.notifications(user_id,actor_id,type,title,body,data,is_read) values(recipient,actor,event_type,message_title,message_body,message_data,false);
 return null;
end; $function$

CREATE OR REPLACE FUNCTION public.prepare_account_deletion(target_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare result jsonb;retained boolean;t text;begin
 if target_user is null then raise exception 'Missing account.';end if;
 perform pg_advisory_xact_lock(hashtextextended(target_user::text,21021));
 select summary into result from public.account_deletion_jobs where user_id=target_user;
 if found then return result;end if;
 perform 1 from auth.users where id=target_user for update;
 if not found then raise exception 'Account not found.';end if;
 perform 1 from public.profiles where id=target_user for update;
 result:=jsonb_build_object('reviewsAnonymized',(select count(*)from public.reviews where user_id=target_user),'commentsAnonymized',(select count(*)from public.review_comments where user_id=target_user),'postsAnonymized',(select count(*)from public.posts where user_id=target_user),'postCommentsAnonymized',(select count(*)from public.post_comments where user_id=target_user),'likesDeleted',(select count(*)from public.review_likes where user_id=target_user)+(select count(*)from public.post_likes where user_id=target_user),'savedDeleted',(select count(*)from public.saved_restaurants where user_id=target_user),'followsDeleted',(select count(*)from public.follows where follower_id=target_user or following_id=target_user),'notificationsDeleted',(select count(*)from public.notifications where user_id=target_user or actor_id=target_user),'pushTokensDeleted',(select count(*)from public.push_tokens where user_id=target_user),'reportsDeleted',(select count(*)from public.review_reports where reported_by_user_id=target_user)+(select count(*)from public.comment_reports where reported_by_user_id=target_user)+(select count(*)from public.post_reports where reported_by_user_id=target_user)+(select count(*)from public.post_comment_reports where reported_by_user_id=target_user),'collectionsDeleted',(select count(*)from public.collections where owner_id=target_user),'claimsDeleted',(select count(*)from public.restaurant_claims where user_id=target_user),'bugReportsDeleted',(select count(*)from public.bug_reports where user_id=target_user),'userDocDeleted',true,'authAccountDeleted',false,'errors','[]'::jsonb);
 insert into public.account_deletion_jobs(user_id,summary)values(target_user,result);
 retained:=exists(select 1 from public.profiles where id=target_user and not is_banned)and not exists(select 1 from public.auth_signup_pending where user_id=target_user);
 foreach t in array array['reviews','review_comments','posts','post_comments']loop execute format('update public.%I set deleted_author_visible=$1 where user_id=$2',t)using retained,target_user;end loop;
 delete from public.notifications where user_id=target_user or actor_id=target_user;
 update public.media_cleanup set state='queued',lease_id=null,lease_owner=null,lease_until=null where lease_owner=target_user and state='processing';
 delete from public.profiles where id=target_user;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.prepare_purchase_intent(request_id uuid, target_restaurant uuid, store_product text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();terms jsonb;r public.purchase_intents;begin
 if not exists(select 1 from public.purchase_settings where id=true and enabled)then raise exception 'Payments are not enabled.';end if;
 if request_id is null or target_restaurant is null then raise exception 'Invalid purchase intent.';end if;
 perform pg_advisory_xact_lock(hashtextextended(request_id::text,25));
 if not exists(select 1 from public.restaurants where id=target_restaurant and owner_id=caller and is_active)then raise exception 'Active restaurant ownership required.';end if;
 select * into r from public.purchase_intents where id=request_id;
 if found then
  if r.buyer_id<>caller or r.restaurant_id<>target_restaurant or r.product_id is distinct from store_product then raise exception 'Purchase intent conflict.';end if;
  return jsonb_build_object('id',r.id,'product_id',r.product_id,'kind',r.kind,'days',r.days,'expires_at',r.expires_at,'fulfilled',r.fulfilled_at is not null);
 end if;
 terms:=public.purchase_product_terms(store_product);
 insert into public.purchase_intents(id,buyer_id,restaurant_id,product_id,kind,days)
  values(request_id,caller,target_restaurant,store_product,terms->>'kind',(terms->>'days')::integer)returning * into r;
 return jsonb_build_object('id',r.id,'product_id',r.product_id,'kind',r.kind,'days',r.days,'expires_at',r.expires_at,'fulfilled',false);
end $function$

CREATE OR REPLACE FUNCTION public.purchase_product_terms(store_product text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare feature jsonb;listing jsonb;plan jsonb;kind text;days integer;begin
 if store_product is null or length(store_product)not between 1 and 200 or store_product!~'^[A-Za-z0-9._-]+$'then raise exception 'Invalid purchase product.';end if;
 select feature_plans,listing_plans into feature,listing from public.app_config where id=true;
 perform public.validate_display_plans(feature,'feature');perform public.validate_display_plans(listing,'listing');
 for plan in select value from jsonb_array_elements(coalesce(feature,'[]'))where value->>'productId'=store_product loop
  kind:='feature';days:=(plan->>'days')::integer;
 end loop;
 for plan in select value from jsonb_array_elements(coalesce(listing,'[]'))where value->>'productId'=store_product loop
  if kind is not null then raise exception 'Ambiguous purchase product.';end if;
  kind:='listing';days:=(plan->>'days')::integer;
 end loop;
 if kind is null then
  if store_product='feature_7d'then kind:='feature';days:=7;
  elsif store_product='feature_30d'then kind:='feature';days:=30;
  elsif store_product='listing_1yr'then kind:='listing';days:=365;
  else raise exception 'Unknown purchase product.';end if;
 end if;
 if(store_product in('feature_7d','feature_30d')and kind<>'feature')or(store_product='listing_1yr'and kind<>'listing')then raise exception 'Ambiguous purchase product.';end if;
 return jsonb_build_object('kind',kind,'days',days);
end $function$

CREATE OR REPLACE FUNCTION public.register_push_token(push_token text, device_platform text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();begin
 if push_token is null or length(push_token)>512 or push_token !~ '^(ExponentPushToken|ExpoPushToken)\[[A-Za-z0-9_-]+\]$'
  or device_platform is null or device_platform not in('ios','android')then raise exception 'Invalid push token or platform.';end if;
 perform pg_advisory_xact_lock(hashtextextended(push_token,0));
 delete from public.push_tokens where token=push_token;
 insert into public.push_tokens(user_id,token,platform)values(caller,push_token,device_platform);
end $function$

CREATE OR REPLACE FUNCTION public.require_active_account()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := auth.uid(); begin
  if caller is null or not exists (select 1 from public.profiles where id=caller and not is_banned)
    or exists (select 1 from public.auth_signup_pending where user_id=caller) then
    raise exception 'You must be signed in to an active account.';
  end if;
  return caller;
end $function$

CREATE OR REPLACE FUNCTION public.retry_notification_push()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare request_id bigint;
begin
 if not exists(select 1 from public.push_deliveries where status in ('pending','processing','failed') and attempts < 5 and (lease_until is null or lease_until < now())) then return null; end if;
 select net.http_post(url := (select decrypted_secret from vault.decrypted_secrets where name='push_sender_url'),headers := jsonb_build_object('Content-Type','application/json','apikey',(select decrypted_secret from vault.decrypted_secrets where name='push_sender_apikey')),body := '{"retry":true}'::jsonb, timeout_milliseconds := 10000) into request_id;
 return request_id;
end; $function$

CREATE OR REPLACE FUNCTION public.search_public_profiles(search_text text)
 RETURNS SETOF public_profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare needle text := lower(btrim(coalesce(search_text, '')));
begin
  if auth.uid() is null then raise exception 'You must be signed in.'; end if;
  if not exists (select 1 from public.profiles where id = auth.uid() and not is_banned)
    or exists (select 1 from public.auth_signup_pending where user_id = auth.uid()) then
    raise exception 'Finish creating an active account first.';
  end if;
  if left(needle, 1) = '@' then needle := substr(needle, 2); end if;
  if length(needle) < 2 then return; end if;
  if length(needle) > 100 then raise exception 'Search is too long.'; end if;
  return query select p.* from public.public_profiles p
    where starts_with(lower(p.username), needle)
      or not exists (select 1 from regexp_split_to_table(needle, '\s+') q
        where not exists (select 1 from regexp_split_to_table(lower(p.display_name), '\s+') word
          where starts_with(word, q)))
    order by starts_with(lower(p.username), needle) desc, p.username, p.id limit 40;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_member_block(target_user uuid, should_block boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();begin
 if target_user is null or should_block is null then raise exception 'Invalid block.';end if;
 if target_user=caller then raise exception 'You can''t block yourself.';end if;
 if should_block then
  if not exists(select 1 from public.profiles where id=target_user)then raise exception 'This account is unavailable.';end if;
  insert into public.blocks(blocker_id,blocked_id)values(caller,target_user)on conflict do nothing;
 else delete from public.blocks where blocker_id=caller and blocked_id=target_user;end if;
 return target_user;
end $function$

CREATE OR REPLACE FUNCTION public.set_member_saved(target_restaurant uuid, saved_list text, should_save boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();begin
 if target_restaurant is null or saved_list is null or saved_list not in('favorite','want_to_go','visited')or should_save is null then raise exception 'Invalid saved restaurant.';end if;
 perform pg_advisory_xact_lock(hashtextextended(caller::text||':'||target_restaurant::text,22022));
 if should_save then
  if not exists(select 1 from public.restaurants where id=target_restaurant and is_active)then raise exception 'Restaurant unavailable.';end if;
  if saved_list in('visited','want_to_go')then delete from public.saved_restaurants where user_id=caller and restaurant_id=target_restaurant and list_type=case saved_list when 'visited'then 'want_to_go'else 'visited'end;end if;
  insert into public.saved_restaurants(user_id,restaurant_id,list_type)values(caller,target_restaurant,saved_list)on conflict(user_id,restaurant_id,list_type)do nothing;
 else delete from public.saved_restaurants where user_id=caller and restaurant_id=target_restaurant and list_type=saved_list;end if;
 return target_restaurant;
end $function$

CREATE OR REPLACE FUNCTION public.submit_content_report(report_kind text, target_id uuid, report_reason text DEFAULT 'inappropriate'::text, report_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := public.require_active_account(); parent uuid; restaurant uuid;
  tab text := public.report_queue_table(report_kind); inserted_count integer; threshold integer;
begin
  if tab is null or report_kind not in ('review','comment','post','post_comment') or target_id is null
    or report_reason is null or report_reason not in ('inappropriate','spam','fake','other')
    or length(coalesce(report_notes,''))>2000 then raise exception 'Invalid report.'; end if;
  if report_kind='review' then
    select restaurant_id into restaurant from public.reviews where id=target_id for update;
    if not found then raise exception 'Review not found.'; end if;
    insert into public.review_reports(review_id,restaurant_id,reported_by_user_id,reason,notes)
      values(target_id,restaurant,caller,report_reason,report_notes) on conflict(review_id,reported_by_user_id) do nothing;
    get diagnostics inserted_count = row_count;
    if inserted_count>0 then
      select review_report_threshold into threshold from public.moderation_config where id=true;
      if threshold is not null and (select count(*) from public.review_reports where review_id=target_id)>=threshold then
        update public.reviews set is_hidden=true where id=target_id;
      end if;
    end if;
  elsif report_kind='comment' then
    select c.review_id,r.restaurant_id into parent,restaurant from public.review_comments c
      join public.reviews r on r.id=c.review_id where c.id=target_id;
    if not found then raise exception 'Comment not found.'; end if;
    insert into public.comment_reports(comment_id,review_id,restaurant_id,reported_by_user_id,reason,notes)
      values(target_id,parent,restaurant,caller,report_reason,report_notes) on conflict(comment_id,reported_by_user_id) do nothing;
  elsif report_kind='post' then
    perform 1 from public.posts where id=target_id;
    if not found then raise exception 'Post not found.'; end if;
    insert into public.post_reports(post_id,reported_by_user_id,reason,notes)
      values(target_id,caller,report_reason,report_notes) on conflict(post_id,reported_by_user_id) do nothing;
  else
    select post_id into parent from public.post_comments where id=target_id;
    if not found then raise exception 'Comment not found.'; end if;
    insert into public.post_comment_reports(comment_id,post_id,reported_by_user_id,reason,notes)
      values(target_id,parent,caller,report_reason,report_notes) on conflict(comment_id,reported_by_user_id) do nothing;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.submit_restaurant_claim(claim_payload jsonb)
 RETURNS restaurant_claims
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := public.require_active_account(); target uuid; result public.restaurant_claims;
  contact_name_value text; phone text; email text; claimant_role_value text; proof text;
begin
  if claim_payload is null or jsonb_typeof(claim_payload)<>'object' or exists(select 1 from jsonb_object_keys(claim_payload) k
    where k not in ('restaurant_id','contact_name','contact_phone','contact_email','claimant_role','proof_note')) then raise exception 'Invalid claim.'; end if;
  if exists(select 1 from jsonb_each(claim_payload) e where jsonb_typeof(e.value)<>'string'
    and not (e.key='proof_note' and e.value='null'::jsonb)) then raise exception 'Invalid claim.'; end if;
  target := (claim_payload->>'restaurant_id')::uuid;
  contact_name_value := btrim(claim_payload->>'contact_name'); phone := btrim(claim_payload->>'contact_phone');
  email := lower(btrim(claim_payload->>'contact_email')); claimant_role_value := claim_payload->>'claimant_role';
  proof := nullif(btrim(claim_payload->>'proof_note'),'');
  if contact_name_value is null or length(contact_name_value) not between 2 and 100
    or phone is null or length(phone)>50 or length(regexp_replace(phone,'\D','','g'))<7
    or email is null or length(email)>320 or email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or claimant_role_value is null or claimant_role_value not in ('owner','manager') or length(coalesce(proof,''))>2000 then
    raise exception 'Check your contact details and restaurant role.';
  end if;
  perform 1 from public.restaurants where id=target and is_active and owner_id is null for update;
  if not found then raise exception 'Restaurant is unavailable or already claimed.'; end if;
  insert into public.restaurant_claims(restaurant_id,user_id,contact_name,contact_phone,contact_email,claimant_role,proof_note)
    values(target,caller,contact_name_value,phone,email,claimant_role_value,proof)
    on conflict(restaurant_id,user_id) where status='pending' do nothing returning * into result;
  if result.id is null then select * into result from public.restaurant_claims where restaurant_id=target and user_id=caller and status='pending'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.update_my_profile(profile_patch jsonb)
 RETURNS SETOF public_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := auth.uid(); current_profile public.profiles; next_username text;
  next_name text; next_bio text; next_avatar text;
begin
  if caller is null then raise exception 'You must be signed in.'; end if;
  select * into current_profile from public.profiles where id = caller for update;
  if not found then raise exception 'Profile not found.'; end if;
  if current_profile.is_banned then raise exception 'This account has been suspended.'; end if;
  if exists (select 1 from public.auth_signup_pending where user_id = caller) then
    raise exception 'Finish creating your account first.';
  end if;
  if profile_patch is null or jsonb_typeof(profile_patch) <> 'object'
    or exists (select 1 from jsonb_object_keys(profile_patch) k
      where k not in ('username', 'display_name', 'bio', 'avatar_path')) then
    raise exception 'Invalid profile update.';
  end if;
  next_username := current_profile.username; next_name := current_profile.display_name;
  next_bio := current_profile.bio; next_avatar := current_profile.avatar_path;
  if profile_patch ? 'username' then
    if jsonb_typeof(profile_patch->'username') <> 'string' then raise exception 'Invalid username.'; end if;
    next_username := lower(btrim(profile_patch->>'username'));
    if next_username !~ '^[a-z0-9_]{3,20}$' then raise exception '3–20 chars: lowercase letters, numbers, underscore'; end if;
  end if;
  if profile_patch ? 'display_name' then
    if jsonb_typeof(profile_patch->'display_name') <> 'string' then raise exception 'Invalid display name.'; end if;
    next_name := btrim(profile_patch->>'display_name');
    if length(next_name) not between 2 and 50 then raise exception 'Display name must be 2–50 characters.'; end if;
  end if;
  if profile_patch ? 'bio' then
    if jsonb_typeof(profile_patch->'bio') not in ('string', 'null') then raise exception 'Invalid bio.'; end if;
    next_bio := profile_patch->>'bio';
    if length(coalesce(next_bio, '')) > 280 then raise exception 'Bio must be 280 characters or less'; end if;
  end if;
  if profile_patch ? 'avatar_path' then
    if jsonb_typeof(profile_patch->'avatar_path') not in ('string', 'null') then raise exception 'Invalid profile photo.'; end if;
    next_avatar := profile_patch->>'avatar_path';
    if next_avatar is not null and (length(next_avatar) > 2048 or
      (next_avatar !~ '^https://[^[:space:]]+$' and
       next_avatar !~ ('^usr/' || caller::text || '/[A-Za-z0-9_-]+\.(jpg|png|webp)$'))) then
      raise exception 'Invalid profile photo.';
    end if;
  end if;
  begin
    update public.profiles set username = next_username, display_name = next_name,
      bio = next_bio, avatar_path = next_avatar where id = caller;
  exception when unique_violation then raise exception 'That username is already taken.'; end;
  if profile_patch ? 'display_name' then
    update auth.users set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
      || jsonb_build_object('display_name', next_name, 'full_name', next_name) where id = caller;
  end if;
  return query select * from public.public_profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_owner_restaurant_menu(target_restaurant uuid, menu_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid := public.require_active_account(); begin
  perform public.validate_restaurant_menu(menu_value);
  perform 1 from public.restaurants where id=target_restaurant and owner_id=caller for update;
  if not found then raise exception 'Only the current restaurant owner can edit this menu.'; end if;
  update public.restaurant_menus set menu=menu_value,updated_at=now() where restaurant_id=target_restaurant;
  if not found then raise exception 'Menu editing is not set up yet. Please contact an admin.'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.validate_display_plans(plans jsonb, plan_kind text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare p jsonb;k text;v jsonb;ids text[]:='{}';products text[]:='{}';begin
 if plans is null or plans='null'::jsonb then return;end if;
 if jsonb_typeof(plans)<>'array'then raise exception 'Invalid plan catalog.';end if;
 if jsonb_array_length(plans)>50 then raise exception 'Too many plans.';end if;
 for p in select value from jsonb_array_elements(plans)loop
  if jsonb_typeof(p)<>'object'then raise exception 'Invalid plan.';end if;
  for k,v in select * from jsonb_each(p)loop
   if k not in('id','label','days','amount','currency','badge','productId')then raise exception 'Invalid plan field.';end if;
  end loop;
  if jsonb_typeof(p->'id')is distinct from 'string'or length(btrim(p->>'id'))<1 or length(p->>'id')>100
   or jsonb_typeof(p->'label')is distinct from 'string'or length(btrim(p->>'label'))<1 or length(p->>'label')>100
   or jsonb_typeof(p->'currency')is distinct from 'string'or(p->>'currency')!~'^[A-Z]{3}$'
   or jsonb_typeof(p->'days')is distinct from 'number'or jsonb_typeof(p->'amount')is distinct from 'number'then raise exception 'Invalid plan details.';end if;
  if(p->>'days')::numeric not between 1 and 3650 or(p->>'days')::numeric<>trunc((p->>'days')::numeric)
   or(p->>'amount')::numeric not between 0 and 1000000000 then raise exception 'Invalid plan duration or amount.';end if;
  if p?'badge'and(jsonb_typeof(p->'badge')<>'string'or length(p->>'badge')>100)then raise exception 'Invalid plan badge.';end if;
  if plan_kind='listing'and not p?'productId'then raise exception 'Listing product is required.';end if;
  if p?'productId'and(jsonb_typeof(p->'productId')<>'string'or length(p->>'productId')not between 1 and 200
   or(p->>'productId')!~'^[A-Za-z0-9._-]+$')then raise exception 'Invalid plan product.';end if;
  if(p->>'id')=any(ids)or(p?'productId'and(p->>'productId')=any(products))then raise exception 'Duplicate plan ID or product.';end if;
  ids:=array_append(ids,p->>'id');if p?'productId'then products:=array_append(products,p->>'productId');end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.validate_restaurant_menu(menu_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare section jsonb; item jsonb; begin
  if menu_value is null or jsonb_typeof(menu_value)<>'array' then raise exception 'Invalid menu.'; end if;
  if jsonb_array_length(menu_value)>100 then raise exception 'Menu is too long.'; end if;
  for section in select value from jsonb_array_elements(menu_value) loop
    if jsonb_typeof(section)<>'object' or jsonb_typeof(section->'title') is distinct from 'string'
      or length(btrim(section->>'title')) not between 1 and 100
      or jsonb_typeof(section->'items') is distinct from 'array' then raise exception 'Invalid menu section.'; end if;
    if jsonb_array_length(section->'items')>200 then raise exception 'Menu section is too long.'; end if;
    for item in select value from jsonb_array_elements(section->'items') loop
      if jsonb_typeof(item)<>'string' or length(item#>>'{}') not between 1 and 240 then raise exception 'Invalid menu item.'; end if;
    end loop;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.validate_review_interaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if tg_op='UPDATE'and tg_table_name='review_comments'then
 if old.user_id is not null and(new.user_id is null or new.user_id=old.user_id)
 and to_jsonb(new)-array['user_id','deleted_author_visible']=to_jsonb(old)-array['user_id','deleted_author_visible']
 and exists(select 1 from public.account_deletion_jobs where user_id=old.user_id and state='prepared')then return new;end if;
 end if;
 if not public.is_active_account()or new.user_id is distinct from auth.uid()then raise exception 'Sign in to interact with reviews.';end if;
 if not exists(select 1 from public.reviews where id=new.review_id and not is_hidden)then raise exception 'Review is unavailable.';end if;
 if tg_table_name='review_comments'then if length(trim(new.text))not between 1 and 1000 or new.text ~* '(https?://|www\.)'then raise exception 'Comments must contain 1–1000 characters and no external links.';end if;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.write_community_comment(content_kind text, target_id uuid, comment_text text, target_restaurant uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();body text:=public.validated_community_text(comment_text,1000);result jsonb;parent uuid;begin
 if not public.community_target_visible(content_kind,target_id)then raise exception 'Content is unavailable.';end if;
 if content_kind='review'then select restaurant_id into parent from public.reviews where id=target_id;
 if target_restaurant is not null and parent<>target_restaurant then raise exception 'Review restaurant does not match.';end if;
 insert into public.review_comments(review_id,user_id,text)values(target_id,caller,body)returning to_jsonb(review_comments)||jsonb_build_object('restaurant_id',parent)into result;
 else insert into public.post_comments(post_id,user_id,text)values(target_id,caller,body)returning to_jsonb(post_comments)into result;end if;return result;end $function$

CREATE OR REPLACE FUNCTION public.write_member_collection(target_collection uuid, collection_patch jsonb)
 RETURNS collections
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();result public.collections;k text;v jsonb;begin
 if collection_patch is null or jsonb_typeof(collection_patch)<>'object'then raise exception 'Invalid collection.';end if;
 for k,v in select * from jsonb_each(collection_patch)loop
  if k not in('title','description','is_public')then raise exception 'Invalid collection field.';end if;
  if k='title'and(jsonb_typeof(v)<>'string'or char_length(btrim(v#>>'{}'))not between 2 and 100)then raise exception 'Collection title must be 2 to 100 characters.';end if;
  if k='description'and jsonb_typeof(v)not in('string','null')then raise exception 'Invalid description.';end if;
  if k='is_public'and jsonb_typeof(v)<>'boolean'then raise exception 'Invalid collection visibility.';end if;
 end loop;
 if target_collection is null then
  if not collection_patch?'title'then raise exception 'Enter a collection title.';end if;
  insert into public.collections(owner_id,title,description,is_public)values(caller,btrim(collection_patch->>'title'),nullif(btrim(collection_patch->>'description'),''),coalesce((collection_patch->>'is_public')::boolean,false))returning * into result;
 else
  select * into result from public.collections where id=target_collection and owner_id=caller for update;
  if not found then raise exception 'Collection not found or permission denied.';end if;
  if collection_patch?'title'then result.title:=btrim(collection_patch->>'title');end if;
  if collection_patch?'description'then result.description:=nullif(btrim(collection_patch->>'description'),'');end if;
  if collection_patch?'is_public'then result.is_public:=(collection_patch->>'is_public')::boolean;end if;
  update public.collections set title=result.title,description=result.description,is_public=result.is_public where id=target_collection and owner_id=caller returning * into result;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.write_owner_response(target_review uuid DEFAULT NULL::uuid, target_restaurant uuid DEFAULT NULL::uuid, response_text text DEFAULT NULL::text, response_id uuid DEFAULT NULL::uuid)
 RETURNS review_responses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();parent uuid;restaurant uuid;existing public.review_responses;result public.review_responses;body text:=btrim(response_text);
begin
 if body is null or length(body) not between 1 and 1000 then raise exception 'Replies must be 1–1000 characters.'; end if;
 if response_id is not null then
  select * into existing from public.review_responses where id=response_id;
  if not found or existing.author_id<>caller then raise exception 'Reply not found or not yours.'; end if;
  if(target_review is not null and target_review<>existing.review_id)or(target_restaurant is not null and target_restaurant<>existing.restaurant_id)then raise exception 'A reply cannot be moved.';end if;
  parent:=existing.review_id;
 else parent:=target_review;end if;
 select r.restaurant_id into restaurant from public.reviews r where r.id=parent and not r.is_hidden;
 if not found or(target_restaurant is not null and target_restaurant<>restaurant)then raise exception 'Review not found.';end if;
 perform 1 from public.restaurants r where r.id=restaurant and r.owner_id=caller for update;
 if not found then raise exception 'Only the current restaurant owner can reply.';end if;
 if not exists(select 1 from public.reviews r where r.id=parent and r.restaurant_id=restaurant and not r.is_hidden)then raise exception 'Review not found.';end if;
 if response_id is null then
  insert into public.review_responses(review_id,restaurant_id,author_id,text)values(parent,restaurant,caller,body)returning * into result;
 else
  update public.review_responses set text=body,updated_at=now()where id=response_id and author_id=caller returning * into result;
  if not found then raise exception 'Reply not found or not yours.';end if;
 end if;return result;
end $function$

CREATE OR REPLACE FUNCTION public.write_review(payload jsonb, review_id uuid DEFAULT NULL::uuid)
 RETURNS reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller uuid:=public.require_active_account();r public.reviews;result public.reviews;k text;v jsonb;old_images text[]:='{}';begin
 if payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Invalid review.';end if;
 for k,v in select * from jsonb_each(payload)loop
  if k not in('restaurant_id','rating','comment','image_paths')or(review_id is not null and k='restaurant_id')then raise exception 'Invalid review field.';end if;
  if k='rating'and(jsonb_typeof(v)<>'number')then raise exception 'Invalid rating.';end if;
  if k='comment'and jsonb_typeof(v)not in('string','null')then raise exception 'Invalid comment.';end if;
  if k='image_paths'and jsonb_typeof(v)not in('array','null')then raise exception 'Invalid review images.';end if;
  if k='image_paths'and jsonb_typeof(v)='array'then
   if exists(select 1 from jsonb_array_elements(v)e where jsonb_typeof(e)<>'string')then raise exception 'Invalid review images.';end if;
  end if;
 end loop;
 if payload?'rating'then
  if(payload->>'rating')::numeric not between 1 and 5 or(payload->>'rating')::numeric<>trunc((payload->>'rating')::numeric)then raise exception 'Invalid rating.';end if;
 end if;
 if review_id is not null then
  select * into r from public.reviews where id=review_id and user_id=caller for update;
  if not found then raise exception 'Review not found or permission denied.';end if;
  old_images:=coalesce(r.image_paths,'{}');
 end if;
 r:=jsonb_populate_record(r,payload);
 if r.rating is null or r.rating not between 1 and 5 or length(coalesce(r.comment,''))>2000
  or cardinality(coalesce(r.image_paths,'{}'))>6 then raise exception 'Check your rating, comment length and image count.';end if;
 if coalesce(r.comment,'')~*'(https?://|www\.)'then raise exception 'External links are not allowed in reviews.';end if;
 if exists(select 1 from unnest(coalesce(r.image_paths,'{}'))p where p is null or length(p)>512
  or(not p=any(old_images)and p !~ ('^rev/'||caller::text||'/[a-zA-Z0-9._-]+[.](jpg|png|webp)$')))then raise exception 'Invalid review images.';end if;
 if review_id is null then
  if not exists(select 1 from public.restaurants where id=r.restaurant_id and is_active)then raise exception 'Restaurant is not available for reviews.';end if;
  insert into public.reviews(restaurant_id,user_id,rating,comment,image_paths,like_count,comment_count,is_edited,is_hidden)
   values(r.restaurant_id,caller,r.rating,r.comment,coalesce(r.image_paths,'{}'),0,0,false,false)returning * into result;
 else
  update public.reviews set rating=r.rating,comment=r.comment,image_paths=coalesce(r.image_paths,'{}'),is_edited=true
   where id=review_id and user_id=caller returning * into result;
 end if;
 return result;
end $function$

create policy "notifications visible actors" on public.notifications as restrictive for select to authenticated using ((is_active_account() AND ((actor_id IS NULL) OR (NOT (EXISTS ( SELECT 1
   FROM blocks
  WHERE (((blocks.blocker_id = auth.uid()) AND (blocks.blocked_id = notifications.actor_id)) OR ((blocks.blocked_id = auth.uid()) AND (blocks.blocker_id = notifications.actor_id)))))))));

create policy "profiles preferences own" on public.profiles as permissive for update to authenticated using (((id = ( SELECT auth.uid() AS uid)) AND (NOT is_banned) AND (NOT (EXISTS ( SELECT 1
   FROM auth_signup_pending s
  WHERE (s.user_id = profiles.id)))))) with check (((id = ( SELECT auth.uid() AS uid)) AND (NOT is_banned)));
